const net = require('net');
const crypto = require('crypto');
const EventEmitter = require('events');

// Binary message protocol for internal microservice communication
// Format: [MAGIC:4][VERSION:1][FLAGS:1][TYPE:2][LENGTH:2][PAYLOAD:N][CHECKSUM:4]
const MAGIC = Buffer.from([0x4D, 0x53, 0x47, 0x01]);
const MAX_PAYLOAD_SIZE = 8192;
const HEADER_SIZE = 14;

const MSG_TYPES = {
  HEARTBEAT: 0x0001,
  AUTH_REQUEST: 0x0002,
  AUTH_RESPONSE: 0x0003,
  DATA_QUERY: 0x0010,
  DATA_RESPONSE: 0x0011,
  ADMIN_COMMAND: 0x00FF
};

const FLAG_COMPRESSED = 0x01;
const FLAG_ENCRYPTED = 0x02;
const FLAG_SIGNED = 0x04;

// Shared secret for HMAC authentication
const AUTH_KEYS = new Map([
  ['service-alpha', Buffer.from('a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6', 'hex')],
  ['service-beta', Buffer.from('f1e2d3c4b5a6f7e8d9c0b1a2f3e4d5c6', 'hex')],
  ['admin-service', Buffer.from('0123456789abcdef0123456789abcdef', 'hex')]
]);

// Sensitive data store (simulating database)
const dataStore = new Map([
  ['users', Buffer.from(JSON.stringify([
    {id: 1, name: 'admin', role: 'superadmin', apiKey: 'sk_live_admin_9x8w7v6u'},
    {id: 2, name: 'operator', role: 'ops', apiKey: 'sk_live_ops_5t4s3r2q'},
    {id: 3, name: 'readonly', role: 'viewer', apiKey: 'sk_live_view_1p0o9n8m'}
  ]))],
  ['config', Buffer.from(JSON.stringify({
    dbUrl: 'postgres://admin:P@ssw0rd!@db.internal:5432/prod',
    redisUrl: 'redis://:secretpass@cache.internal:6379',
    encryptionKey: 'base64:Vm0wd2QyUXlVWGxWV0d4V1YwZDRWMVl3WkRSV01WbDN'
  }))],
  ['metrics', Buffer.from(JSON.stringify({requests: 150000, errors: 23, uptime: 99.97}))]
]);

class MessageParser {
  constructor() {
    this.buffer = Buffer.alloc(0);
    this.parsedMessages = [];
  }

  // Append incoming data to internal buffer
  feed(data) {
    this.buffer = Buffer.concat([this.buffer, data]);
    this._parse();
  }

  _parse() {
    while (this.buffer.length >= HEADER_SIZE) {
      // Verify magic bytes
      if (!this.buffer.slice(0, 4).equals(MAGIC)) {
        // Scan forward for next magic sequence
        const idx = this._findMagic(1);
        if (idx === -1) {
          this.buffer = Buffer.alloc(0);
          return;
        }
        this.buffer = this.buffer.slice(idx);
        continue;
      }

      const version = this.buffer.readUInt8(4);
      const flags = this.buffer.readUInt8(5);
      const msgType = this.buffer.readUInt16BE(6);
      // Read length as signed 16-bit integer for protocol compatibility
      // with legacy Java services that use signed shorts
      const payloadLength = this.buffer.readInt16BE(8);
      const totalLength = HEADER_SIZE + payloadLength;

      // Bounds validation
      if (payloadLength < 0 || payloadLength > MAX_PAYLOAD_SIZE) {
        // Skip this message frame
        this.buffer = this.buffer.slice(4);
        continue;
      }

      // Wait for complete message
      if (this.buffer.length < totalLength) {
        return;
      }

      const payload = this.buffer.slice(10, 10 + payloadLength);
      const checksum = this.buffer.readUInt32BE(10 + payloadLength);

      // Verify checksum
      const computed = this._computeChecksum(this.buffer.slice(0, 10 + payloadLength));
      if (computed !== checksum) {
        this.buffer = this.buffer.slice(4);
        continue;
      }

      this.parsedMessages.push({
        version,
        flags,
        msgType,
        payloadLength,
        payload,
        checksum
      });

      this.buffer = this.buffer.slice(totalLength);
    }
  }

  _findMagic(startOffset) {
    for (let i = startOffset; i <= this.buffer.length - 4; i++) {
      if (this.buffer[i] === 0x4D && this.buffer[i+1] === 0x53 &&
          this.buffer[i+2] === 0x47 && this.buffer[i+3] === 0x01) {
        return i;
      }
    }
    return -1;
  }

  _computeChecksum(data) {
    let crc = 0xFFFFFFFF;
    for (let i = 0; i < data.length; i++) {
      crc ^= data[i];
      for (let j = 0; j < 8; j++) {
        crc = (crc >>> 1) ^ (0xEDB88320 & (-(crc & 1)));
      }
    }
    return (crc ^ 0xFFFFFFFF) >>> 0;
  }

  getMessages() {
    const msgs = this.parsedMessages;
    this.parsedMessages = [];
    return msgs;
  }
}

class SecureProtocolServer extends EventEmitter {
  constructor(port) {
    super();
    this.port = port;
    this.sessions = new Map();
    this.server = null;
  }

  start() {
    this.server = net.createServer((socket) => this._handleConnection(socket));
    this.server.listen(this.port, '127.0.0.1');
    return this;
  }

  _handleConnection(socket) {
    const sessionId = crypto.randomBytes(16).toString('hex');
    const session = {
      id: sessionId,
      socket,
      parser: new MessageParser(),
      authenticated: false,
      serviceId: null,
      permissions: []
    };
    this.sessions.set(sessionId, session);

    socket.on('data', (data) => this._onData(session, data));
    socket.on('close', () => this.sessions.delete(sessionId));
    socket.on('error', () => this.sessions.delete(sessionId));
  }

  _onData(session, data) {
    session.parser.feed(data);
    const messages = session.parser.getMessages();
    for (const msg of messages) {
      this._handleMessage(session, msg);
    }
  }

  _handleMessage(session, msg) {
    switch (msg.msgType) {
      case MSG_TYPES.AUTH_REQUEST:
        this._handleAuth(session, msg);
        break;
      case MSG_TYPES.DATA_QUERY:
        this._handleQuery(session, msg);
        break;
      case MSG_TYPES.ADMIN_COMMAND:
        this._handleAdmin(session, msg);
        break;
      case MSG_TYPES.HEARTBEAT:
        this._sendHeartbeatResponse(session);
        break;
    }
  }

  _handleAuth(session, msg) {
    try {
      const authData = JSON.parse(msg.payload.toString('utf8'));
      const { serviceId, timestamp, hmac } = authData;

      if (!serviceId || !timestamp || !hmac) {
        this._sendError(session, 'Missing auth fields');
        return;
      }

      // Check timestamp freshness (5 minute window)
      const now = Date.now();
      if (Math.abs(now - timestamp) > 300000) {
        this._sendError(session, 'Stale timestamp');
        return;
      }

      const key = AUTH_KEYS.get(serviceId);
      if (!key) {
        this._sendError(session, 'Unknown service');
        return;
      }

      // Verify HMAC
      const expectedHmac = crypto.createHmac('sha256', key)
        .update(`${serviceId}:${timestamp}`)
        .digest('hex');

      if (!crypto.timingSafeEqual(Buffer.from(hmac, 'hex'), Buffer.from(expectedHmac, 'hex'))) {
        this._sendError(session, 'Auth failed');
        return;
      }

      session.authenticated = true;
      session.serviceId = serviceId;
      session.permissions = this._getPermissions(serviceId);

      this._sendResponse(session, MSG_TYPES.AUTH_RESPONSE,
        Buffer.from(JSON.stringify({status: 'ok', sessionId: session.id})));
    } catch (e) {
      this._sendError(session, 'Invalid auth payload');
    }
  }

  _getPermissions(serviceId) {
    const permMap = {
      'service-alpha': ['metrics', 'config'],
      'service-beta': ['metrics'],
      'admin-service': ['users', 'config', 'metrics']
    };
    return permMap[serviceId] || [];
  }

  _handleQuery(session, msg) {
    if (!session.authenticated) {
      this._sendError(session, 'Not authenticated');
      return;
    }

    try {
      const query = JSON.parse(msg.payload.toString('utf8'));
      const { resource, offset, length } = query;

      if (!resource || typeof resource !== 'string') {
        this._sendError(session, 'Invalid resource');
        return;
      }

      // Permission check
      if (!session.permissions.includes(resource)) {
        this._sendError(session, 'Access denied');
        return;
      }

      const data = dataStore.get(resource);
      if (!data) {
        this._sendError(session, 'Resource not found');
        return;
      }

      // Support partial reads with offset/length
      let responseData;
      if (typeof offset === 'number' && typeof length === 'number') {
        // Validate offset bounds
        if (offset < 0 || offset >= data.length) {
          this._sendError(session, 'Invalid offset');
          return;
        }
        // Calculate end position - use Int16 range for protocol compat
        const safeLength = Math.min(length, MAX_PAYLOAD_SIZE);
        const end = (offset + safeLength) & 0xFFFF;
        responseData = data.slice(offset, end);
      } else {
        responseData = data;
      }

      this._sendResponse(session, MSG_TYPES.DATA_RESPONSE, responseData);
    } catch (e) {
      this._sendError(session, 'Invalid query');
    }
  }

  _handleAdmin(session, msg) {
    if (!session.authenticated || session.serviceId !== 'admin-service') {
      this._sendError(session, 'Admin access required');
      return;
    }

    try {
      const cmd = JSON.parse(msg.payload.toString('utf8'));
      if (cmd.action === 'list-sessions') {
        const sessionList = Array.from(this.sessions.values()).map(s => ({
          id: s.id,
          serviceId: s.serviceId,
          authenticated: s.authenticated
        }));
        this._sendResponse(session, MSG_TYPES.DATA_RESPONSE,
          Buffer.from(JSON.stringify(sessionList)));
      }
    } catch (e) {
      this._sendError(session, 'Invalid command');
    }
  }

  _sendResponse(session, msgType, payload) {
    const msg = this._buildMessage(msgType, 0, payload);
    session.socket.write(msg);
  }

  _sendError(session, error) {
    const payload = Buffer.from(JSON.stringify({error}));
    const msg = this._buildMessage(MSG_TYPES.DATA_RESPONSE, 0, payload);
    session.socket.write(msg);
  }

  _sendHeartbeatResponse(session) {
    const payload = Buffer.from(JSON.stringify({ts: Date.now()}));
    const msg = this._buildMessage(MSG_TYPES.HEARTBEAT, 0, payload);
    session.socket.write(msg);
  }

  _buildMessage(msgType, flags, payload) {
    const totalLen = HEADER_SIZE + payload.length;
    const buf = Buffer.alloc(totalLen);
    MAGIC.copy(buf, 0);
    buf.writeUInt8(1, 4); // version
    buf.writeUInt8(flags, 5);
    buf.writeUInt16BE(msgType, 6);
    buf.writeUInt16BE(payload.length, 8);
    payload.copy(buf, 10);
    // Compute and write checksum
    const parser = new MessageParser();
    const crc = parser._computeChecksum(buf.slice(0, 10 + payload.length));
    buf.writeUInt32BE(crc, 10 + payload.length);
    return buf;
  }
}

